INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000dd',1,'APPROVED','PUBLISHED',
'{"objectives":["Understand the German healthcare system","Discuss Kassenarzt vs Privatarzt","Use healthcare vocabulary"],"explanation":{"intro":"The German healthcare system (Gesundheitssystem) is a two-tier system with statutory (gesetzlich) and private (privat) insurance. Understanding it is essential for anyone living in Germany.","culturalNote":"Germany has one of the world''s oldest healthcare systems — Bismarck introduced it in 1883. The dual system of GKV (gesetzliche Krankenversicherung) and PKV (private Krankenversicherung) creates a complex landscape. Most residents use GKV, with about 10% in PKV."},"examples":[{"german":"Ich bin gesetzlich krankenversichert und habe einen Kassenarzt.","english":"I have statutory health insurance and have a panel doctor."},{"german":"Mit der Überweisung kann ich zum Spezialisten gehen.","english":"With the referral I can go to the specialist."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can navigate and discuss the German healthcare system."}}',
'{"items":[{"word":"gesetzlich versichert","translation":"statutorily insured","pronunciation":"geh-ZETS-likh fer-ZIKH-ert","example":"Gesetzlich versichert sein."},{"word":"der Kassenarzt","translation":"panel doctor (GKV)","pronunciation":"dayr KAS-en-arzt","example":"Zum Kassenarzt gehen."},{"word":"die Überweisung","translation":"referral","pronunciation":"dee ü-ber-VY-zoong","example":"Eine Überweisung bekommen."},{"word":"der Facharzt","translation":"specialist","pronunciation":"dayr FAKH-arzt","example":"Zum Facharzt."},{"word":"die Praxisgebühr","translation":"practice fee (historical)","pronunciation":"dee PRAK-sis-geh-bür","example":"Früher Praxisgebühr."},{"word":"die Notaufnahme","translation":"emergency room","pronunciation":"dee NOT-owf-nah-meh","example":"In die Notaufnahme."}]}',
'{"title":"Gesetzlich vs privat versichert","pattern":"gesetzlich (statutory GKV) vs. privat (PKV) — verb: versichert sein bei","explanation":"Versichert sein bei + insurance company. Ich bin bei der AOK versichert = I am insured with the AOK (statutory). Überweisung (referral) is needed to see a Facharzt (specialist) with GKV — not with PKV. Krankenkasse = statutory health insurer. Krankenversicherung = health insurance (general). Chipkarte/Gesundheitskarte = insurance card shown at appointments.","examples":[{"sentence":"Ich bin bei der Techniker Krankenkasse versichert.","translation":"I am insured with the Techniker health fund."},{"sentence":"Für den Spezialisten brauche ich eine Überweisung.","translation":"For the specialist I need a referral."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Notaufnahme'' means?","options":["emergency room","hospital admission","urgent care","accident unit"],"correctAnswer":"emergency room"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have statutory health insurance and have a panel doctor.","options":["Ich bin gesetzlich krankenversichert und habe einen Kassenarzt.","Ich habe Krankenversicherung.","Ich bin privat versichert.","Ich gehe zum Arzt."],"correctAnswer":"Ich bin gesetzlich krankenversichert und habe einen Kassenarzt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Für den Spezialisten brauche ich eine ___.","options":["Überweisung","Empfehlung","Zuweisung","Bescheinigung"],"correctAnswer":"Überweisung"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: I am insured with the Techniker health fund","wordBankItems":["Ich","bin","bei","der","Techniker","Krankenkasse","versichert","."],"correctAnswer":"Ich bin bei der Techniker Krankenkasse versichert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"To see a specialist with GKV insurance, you usually need?","options":["a referral (Überweisung)","prior approval","extra payment","private insurance"],"correctAnswer":"a referral (Überweisung)"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000de',1,'APPROVED','PUBLISHED',
'{"objectives":["Describe symptoms in detail","Understand a diagnosis","Discuss treatment options"],"explanation":{"intro":"Medical German at B1 involves describing symptoms precisely, understanding diagnoses, and discussing treatment options.","culturalNote":"Germans tend to be very precise about health — describing symptoms accurately is expected. The Hausarzt (GP) is the first point of contact. Specialists require a referral. Pharmacies (Apotheken) are on every corner and pharmacists are trusted advisors."},"examples":[{"german":"Ich habe seit drei Tagen stechende Kopfschmerzen.","english":"I have had stabbing headaches for three days."},{"german":"Der Arzt hat mir ein Medikament verschrieben, das ich zweimal täglich einnehmen soll.","english":"The doctor prescribed me a medication I should take twice daily."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can describe symptoms precisely and discuss medical treatment in German."}}',
'{"items":[{"word":"stechend","translation":"stabbing/piercing (pain)","pronunciation":"SHTEKH-end","example":"Stechende Schmerzen."},{"word":"verschreiben","translation":"to prescribe","pronunciation":"fer-SHRY-ben","example":"Ein Medikament verschreiben."},{"word":"einnehmen","translation":"to take (medication)","pronunciation":"YN-ney-men","example":"Tabletten einnehmen."},{"word":"die Nebenwirkung","translation":"side effect","pronunciation":"dee NAY-ben-vir-koong","example":"Nebenwirkungen beachten."},{"word":"die Diagnose","translation":"diagnosis","pronunciation":"dee dee-ag-NOH-zeh","example":"Eine Diagnose stellen."},{"word":"erholen sich von","translation":"to recover from","pronunciation":"er-HOH-len zikh fon","example":"Sich von Krankheit erholen."}]}',
'{"title":"Seit + present tense — duration of symptoms","pattern":"seit + time expression + present tense (for symptoms that have been ongoing)","explanation":"Seit (since/for — with ongoing situations) + present tense: Ich habe seit drei Tagen Kopfschmerzen = I have had a headache for three days (and still do). Contrast with English perfect. Seit wann? = Since when? / For how long? Seit gestern = since yesterday. Schmerzen (plural): Der Kopf schmerzt = My head hurts; Ich habe Kopfschmerzen = I have a headache.","examples":[{"sentence":"Ich habe seit einer Woche Fieber.","translation":"I have had a fever for a week."},{"sentence":"Seit dem Unfall habe ich Rückenschmerzen.","translation":"Since the accident I have had back pain."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Nebenwirkung'' means?","options":["side effect","secondary effect","reaction","consequence"],"correctAnswer":"side effect"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I have had stabbing headaches for three days.","options":["Ich habe seit drei Tagen stechende Kopfschmerzen.","Ich hatte drei Tage Kopfschmerzen.","Mein Kopf schmerzt seit Tagen.","Drei Tage Kopfschmerzen."],"correctAnswer":"Ich habe seit drei Tagen stechende Kopfschmerzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich habe ___ einer Woche Fieber.","options":["seit","für","vor","ab"],"correctAnswer":"seit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Since the accident I have had back pain","wordBankItems":["Seit","dem","Unfall","habe","ich","Rückenschmerzen","."],"correctAnswer":"Seit dem Unfall habe ich Rückenschmerzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verschreiben'' means?","options":["to prescribe","to write a prescription","to recommend","to diagnose"],"correctAnswer":"to prescribe"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000df',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate a German hospital","Know ward and procedure vocabulary","Communicate with hospital staff"],"explanation":{"intro":"Hospital vocabulary is essential for emergencies and planned procedures. German hospitals have specific vocabulary for wards, procedures, and staff.","culturalNote":"German hospitals (Krankenhäuser) are either public (öffentlich), confessional (kirchlich), or private (privat). Patients wear their own pyjamas — bringing nightwear is expected. Visiting hours (Besuchszeiten) are strictly observed. Kaffeeklatsch with fellow patients is common."},"examples":[{"german":"Ich wurde auf die Innere Abteilung eingewiesen.","english":"I was admitted to the internal medicine ward."},{"german":"Die Operation dauerte drei Stunden.","english":"The operation took three hours."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can communicate in a German hospital setting."}}',
'{"items":[{"word":"einweisen","translation":"to admit (to hospital)","pronunciation":"YN-vy-zen","example":"Ins Krankenhaus eingewiesen."},{"word":"die Abteilung","translation":"ward/department","pronunciation":"dee ap-TY-loong","example":"Die Innere Abteilung."},{"word":"die Operation","translation":"operation/surgery","pronunciation":"dee op-er-ah-TSYOHN","example":"Eine Operation."},{"word":"die Narkose","translation":"anaesthesia","pronunciation":"dee nar-KOH-zeh","example":"In Narkose."},{"word":"der Chirurg","translation":"surgeon","pronunciation":"dayr khee-ROORK","example":"Der Chirurg operiert."},{"word":"entlassen werden","translation":"to be discharged","pronunciation":"ent-LAS-en VER-den","example":"Aus dem Krankenhaus entlassen."}]}',
'{"title":"Eingewiesen werden — passive for hospital admission","pattern":"jemanden einweisen (to admit) → ins Krankenhaus eingewiesen werden (to be admitted)","explanation":"Einweisen (to assign/admit): Ich wurde ins Krankenhaus eingewiesen = I was admitted to hospital. Passive with werden. Entlassen (discharge): Ich wurde nach drei Tagen entlassen = I was discharged after three days. Abteilung (ward/department): Innere Medizin (internal medicine), Chirurgie (surgery), Orthopädie (orthopaedics).","examples":[{"sentence":"Er wurde nach einem Unfall in die Notaufnahme eingewiesen.","translation":"He was admitted to the emergency room after an accident."},{"sentence":"Nach der Operation wurde sie schnell entlassen.","translation":"After the operation she was discharged quickly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Narkose'' means?","options":["anaesthesia","sedation","painkiller","narcotic"],"correctAnswer":"anaesthesia"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I was admitted to the internal medicine ward.","options":["Ich wurde auf die Innere Abteilung eingewiesen.","Ich lag auf der Inneren Abteilung.","Ich wurde eingewiesen.","Die Innere Abteilung hat mich aufgenommen."],"correctAnswer":"Ich wurde auf die Innere Abteilung eingewiesen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Nach der Operation wurde sie schnell ___.","options":["entlassen","eingewiesen","aufgenommen","behandelt"],"correctAnswer":"entlassen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: After the operation she was discharged quickly","wordBankItems":["Nach","der","Operation","wurde","sie","schnell","entlassen","."],"correctAnswer":"Nach der Operation wurde sie schnell entlassen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Chirurg'' means?","options":["surgeon","doctor","consultant","specialist"],"correctAnswer":"surgeon"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss mental health in German","Use Psyche and Wohlbefinden vocabulary","Reduce stigma through language"],"explanation":{"intro":"Mental health vocabulary is increasingly important and normalised. B1 learners should be able to discuss wellbeing, stress, and mental health support.","culturalNote":"Mental health (psychische Gesundheit) is an increasingly open topic in Germany. Burnout (recognised as a diagnosis), Stress, and Erschöpfung are commonly discussed. Psychotherapy (Psychotherapie) is covered by Krankenkassen, though waiting times can be long."},"examples":[{"german":"Ich fühle mich ausgebrannt und brauche eine Pause.","english":"I feel burnt out and need a break."},{"german":"Psychotherapie hat mir sehr geholfen, mit dem Stress umzugehen.","english":"Psychotherapy helped me a lot to cope with the stress."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss mental health and wellbeing in German."}}',
'{"items":[{"word":"ausgebrannt","translation":"burnt out","pronunciation":"OWS-geh-brant","example":"Ich bin ausgebrannt."},{"word":"die Erschöpfung","translation":"exhaustion","pronunciation":"dee er-SHÖP-foong","example":"Totale Erschöpfung."},{"word":"umgehen mit","translation":"to cope with/deal with","pronunciation":"OOM-gay-en mit","example":"Mit Stress umgehen."},{"word":"die Psychotherapie","translation":"psychotherapy","pronunciation":"dee psü-khoh-ter-ah-PEE","example":"In Psychotherapie gehen."},{"word":"das Wohlbefinden","translation":"wellbeing","pronunciation":"dahs VOHL-beh-fin-den","example":"Das Wohlbefinden fördern."},{"word":"der Burnout","translation":"burnout","pronunciation":"dayr BURN-owt","example":"Einen Burnout haben."}]}',
'{"title":"Umgehen mit — to cope/deal with","pattern":"umgehen mit + dative (to deal with/cope with something)","explanation":"Umgehen mit (separable): Ich gehe mit dem Stress um = I cope with the stress. Infinitive: mit etwas umgehen. Ich weiß nicht, wie ich damit umgehen soll = I don''t know how to deal with it. Note: umgehen can also mean to bypass/circumvent (non-separable): Er umgeht das Problem = He bypasses the problem. Context distinguishes them.","examples":[{"sentence":"Es ist wichtig zu lernen, wie man mit Niederlagen umgeht.","translation":"It is important to learn how to deal with setbacks."},{"sentence":"Sie geht sehr gut mit schwierigen Situationen um.","translation":"She deals very well with difficult situations."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Erschöpfung'' means?","options":["exhaustion","fatigue","burnout","tiredness"],"correctAnswer":"exhaustion"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I feel burnt out and need a break.","options":["Ich fühle mich ausgebrannt und brauche eine Pause.","Ich bin müde und erschöpft.","Ich brauche Urlaub.","Ich habe Burnout."],"correctAnswer":"Ich fühle mich ausgebrannt und brauche eine Pause."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie geht sehr gut mit schwierigen Situationen ___.","options":["um","mit","durch","auf"],"correctAnswer":"um"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: It is important to learn how to deal with setbacks","wordBankItems":["Es","ist","wichtig","zu","lernen",",","wie","man","mit","Niederlagen","umgeht","."],"correctAnswer":"Es ist wichtig zu lernen , wie man mit Niederlagen umgeht ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausgebrannt'' literally means and is used for?","options":["burnt out — used for exhaustion/burnout","on fire — used for anger","burned — used for sunburn","fired — used for job loss"],"correctAnswer":"burnt out — used for exhaustion/burnout"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss nutrition and diet scientifically","Use Nährstoff and Ernährung vocabulary","Talk about dietary choices"],"explanation":{"intro":"Nutrition science vocabulary at B1 allows discussing diet and health evidence-based choices.","culturalNote":"Germans are interested in Ernährung (nutrition) and food quality. Organic (Bio) food is popular. The Vollwertkost (whole food) movement originated partly in Germany. Vegetarianism and veganism have grown significantly."},"examples":[{"german":"Eine ausgewogene Ernährung enthält alle notwendigen Nährstoffe.","english":"A balanced diet contains all necessary nutrients."},{"german":"Übermäßiger Zuckerkonsum kann zu Übergewicht führen.","english":"Excessive sugar consumption can lead to being overweight."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss nutrition and healthy eating scientifically in German."}}',
'{"items":[{"word":"der Nährstoff","translation":"nutrient","pronunciation":"dayr NÄR-shtof","example":"Wichtige Nährstoffe."},{"word":"ausgewogen","translation":"balanced","pronunciation":"OWS-geh-voh-gen","example":"Ausgewogene Ernährung."},{"word":"übermäßig","translation":"excessive","pronunciation":"ü-ber-MÄ-sikh","example":"Übermäßiger Konsum."},{"word":"das Übergewicht","translation":"overweight/excess weight","pronunciation":"dahs ü-ber-geh-VIKHT","example":"Übergewicht haben."},{"word":"der Ballaststoff","translation":"dietary fibre","pronunciation":"dayr BAL-ast-shtof","example":"Ballaststoffe wichtig."},{"word":"der Kalorienbedarf","translation":"calorie requirement","pronunciation":"dayr kah-loh-REE-en-beh-darf","example":"Kalorienbedarf decken."}]}',
'{"title":"Führen zu — to lead to (causal chain)","pattern":"etwas führt zu + dative (something leads to/results in)","explanation":"Führen zu + dative: Das führt zu Problemen = That leads to problems. Übermäßiger Konsum führt zu Übergewicht = Excessive consumption leads to being overweight. Note: zu is a dative preposition here. Past: Das hat zu Problemen geführt. This pattern is very useful for scientific and causal arguments.","examples":[{"sentence":"Regelmäßige Bewegung führt zu einem gesunden Körper.","translation":"Regular exercise leads to a healthy body."},{"sentence":"Stress kann zu Schlafproblemen führen.","translation":"Stress can lead to sleep problems."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Ballaststoff'' means?","options":["dietary fibre","ballast","filler","roughage"],"correctAnswer":"dietary fibre"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A balanced diet contains all necessary nutrients.","options":["Eine ausgewogene Ernährung enthält alle notwendigen Nährstoffe.","Gesunde Ernährung ist wichtig.","Man braucht alle Nährstoffe.","Essen enthält Nährstoffe."],"correctAnswer":"Eine ausgewogene Ernährung enthält alle notwendigen Nährstoffe."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Stress kann zu Schlafproblemen ___.","options":["führen","leiten","bringen","kommen"],"correctAnswer":"führen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Regular exercise leads to a healthy body","wordBankItems":["Regelmäßige","Bewegung","führt","zu","einem","gesunden","Körper","."],"correctAnswer":"Regelmäßige Bewegung führt zu einem gesunden Körper ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausgewogen'' means?","options":["balanced","equal","proportional","moderate"],"correctAnswer":"balanced"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss sport and competition","Use Leistung and Wettkampf vocabulary","Talk about victory and defeat"],"explanation":{"intro":"Sport vocabulary at B1 covers competition, athletic performance, and discussing sporting events.","culturalNote":"Sport plays a major role in German life. Football (Fußball) is the most popular sport. The DFB (Deutscher Fußball-Bund) is one of the largest sports associations in the world. Verein (sports club) culture is strong — millions of Germans are club members. The Berlin Marathon and Hamburg Marathon are world-famous."},"examples":[{"german":"Die Mannschaft hat das Spiel mit drei zu null gewonnen.","english":"The team won the game three to nil."},{"german":"Der Athlet hat einen neuen Weltrekord aufgestellt.","english":"The athlete set a new world record."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss sport, competition, and athletic performance in German."}}',
'{"items":[{"word":"die Mannschaft","translation":"team","pronunciation":"dee MAN-shaft","example":"Die Mannschaft spielte."},{"word":"der Weltrekord","translation":"world record","pronunciation":"dayr VELT-reh-kord","example":"Einen Weltrekord aufstellen."},{"word":"aufstellen","translation":"to set (a record)","pronunciation":"OWF-shtel-en","example":"Einen Rekord aufstellen."},{"word":"der Athlet","translation":"athlete","pronunciation":"dayr at-LAYT","example":"Ein professioneller Athlet."},{"word":"der Wettkampf","translation":"competition/contest","pronunciation":"dayr VET-kampf","example":"Am Wettkampf teilnehmen."},{"word":"unentschieden","translation":"draw/tied","pronunciation":"OON-ent-shee-den","example":"Das Spiel endete unentschieden."}]}',
'{"title":"Aufstellen — to set up/establish/set (records)","pattern":"einen Rekord aufstellen (to set a record) — separable","explanation":"Aufstellen (separable) = to set up, to establish, to deploy. Einen Rekord aufstellen = to set a record. Die Mannschaft aufstellen = to select/name the team. Aufstellen is very flexible. Note: Rekord brechen (break a record) vs aufstellen (set/establish a new one). Compound: Er stellte einen neuen Weltrekord auf.","examples":[{"sentence":"Die Sportlerin hat ihre persönliche Bestleistung aufgestellt.","translation":"The athlete set her personal best performance."},{"sentence":"Der Trainer hat eine neue Taktik aufgestellt.","translation":"The coach established a new tactic."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unentschieden'' means?","options":["draw/tied","undecided","equal","balanced"],"correctAnswer":"draw/tied"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The athlete set a new world record.","options":["Der Athlet hat einen neuen Weltrekord aufgestellt.","Der Athlet hat gewonnen.","Ein neuer Weltrekord wurde gebrochen.","Der Athlet spielte gut."],"correctAnswer":"Der Athlet hat einen neuen Weltrekord aufgestellt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Sportlerin hat ihre persönliche Bestleistung ___.","options":["aufgestellt","aufgestellt haben","aufstellen","aufgesteilt"],"correctAnswer":"aufgestellt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The team won the game three to nil","wordBankItems":["Die","Mannschaft","hat","das","Spiel","mit","drei","zu","null","gewonnen","."],"correctAnswer":"Die Mannschaft hat das Spiel mit drei zu null gewonnen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Wettkampf'' means?","options":["competition/contest","match","tournament","fight"],"correctAnswer":"competition/contest"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss travel and adventure","Use Backpacking and Ruckreise vocabulary","Talk about travel experiences"],"explanation":{"intro":"Travel vocabulary at B1 covers planning, experiences, and discussing different travel styles.","culturalNote":"Germans are among the world''s biggest travellers — the Fernweh (wanderlust) is strong. German tourists are known for their thoroughness — guide books (Reiseführer), travel planning (Reiseplanung), and trip reports (Reiseberichte) are taken seriously. The Rucksackreisender (backpacker) culture is also popular."},"examples":[{"german":"Ich bin durch Südostasien gereist und habe viele Kulturen kennengelernt.","english":"I travelled through Southeast Asia and got to know many cultures."},{"german":"Auf Reisen lernt man viel über sich selbst.","english":"While travelling one learns a lot about oneself."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss travel, adventures, and travel experiences in German."}}',
'{"items":[{"word":"der Rucksackreisende","translation":"backpacker","pronunciation":"dayr ROK-zak-ry-zen-deh","example":"Als Rucksackreisender."},{"word":"das Fernweh","translation":"wanderlust","pronunciation":"dahs FERN-vay","example":"Fernweh haben."},{"word":"erleben","translation":"to experience","pronunciation":"er-LAY-ben","example":"Etwas erleben."},{"word":"die Einheimischen","translation":"locals","pronunciation":"dee YN-hy-mish-en","example":"Die Einheimischen fragen."},{"word":"unterwegs sein","translation":"to be on the road/travelling","pronunciation":"OON-ter-vayks zyn","example":"Unterwegs sein."},{"word":"die Sehenswürdigkeit","translation":"sight/attraction","pronunciation":"dee ZAY-ens-vür-dikh-kyt","example":"Sehenswürdigkeiten besuchen."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Fernweh'' means?","options":["wanderlust","homesickness","travel fever","jet lag"],"correctAnswer":"wanderlust"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I travelled through Southeast Asia and got to know many cultures.","options":["Ich bin durch Südostasien gereist und habe viele Kulturen kennengelernt.","Ich war in Südostasien.","Ich kenne viele Kulturen.","Südostasien ist interessant."],"correctAnswer":"Ich bin durch Südostasien gereist und habe viele Kulturen kennengelernt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die ___ fragen ist immer eine gute Idee.","options":["Einheimischen","Touristen","Reisenden","Menschen"],"correctAnswer":"Einheimischen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: While travelling one learns a lot about oneself","wordBankItems":["Auf","Reisen","lernt","man","viel","über","sich","selbst","."],"correctAnswer":"Auf Reisen lernt man viel über sich selbst ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Sehenswürdigkeit'' means?","options":["sight/tourist attraction","worth seeing","view","landmark"],"correctAnswer":"sight/tourist attraction"}]}',
'{"title":"Kennenlernen — to get to know","pattern":"kennenlernen (separable) — to get to know, meet for first time","explanation":"Kennenlernen = to get to know / meet (for the first time). Ich habe viele Kulturen kennengelernt = I got to know many cultures. Ich lerne dich kennen = I am getting to know you. Perfekt: kennengelernt (not *gekennengelernt). Compare: kennen = to know (already): Ich kenne sie = I know her.","examples":[{"sentence":"Auf der Reise habe ich viele interessante Menschen kennengelernt.","translation":"On the trip I got to know many interesting people."},{"sentence":"Ich möchte die Kultur besser kennenlernen.","translation":"I would like to get to know the culture better."}]}','{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Fernweh'' means?","options":["wanderlust","homesickness","travel fever","jet lag"],"correctAnswer":"wanderlust"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I travelled through Southeast Asia and got to know many cultures.","options":["Ich bin durch Südostasien gereist und habe viele Kulturen kennengelernt.","Ich war in Südostasien.","Ich kenne viele Kulturen.","Südostasien ist interessant."],"correctAnswer":"Ich bin durch Südostasien gereist und habe viele Kulturen kennengelernt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die ___ fragen ist immer eine gute Idee.","options":["Einheimischen","Touristen","Reisenden","Menschen"],"correctAnswer":"Einheimischen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: While travelling one learns a lot about oneself","wordBankItems":["Auf","Reisen","lernt","man","viel","über","sich","selbst","."],"correctAnswer":"Auf Reisen lernt man viel über sich selbst ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"The Perfekt of ''kennenlernen'' is?","options":["kennengelernt","gelernt","gekennengelernt","kennengelernt haben"],"correctAnswer":"kennengelernt"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss intercultural communication","Use Missverständnis vocabulary","Express cultural sensitivity"],"explanation":{"intro":"Intercultural communication skills are essential for anyone operating across cultures. B1 introduces discussing and reflecting on cultural differences constructively.","culturalNote":"Germany is increasingly multicultural. Interkulturelles Lernen (intercultural learning) is a key educational goal. The concept of Kulturschock (culture shock) and integration (Integration) are discussed publicly. Vorurteil (prejudice) and Klischee (stereotype) are important vocabulary."},"examples":[{"german":"Kulturelle Missverständnisse entstehen oft durch unterschiedliche Kommunikationsstile.","english":"Cultural misunderstandings often arise from different communication styles."},{"german":"Es ist wichtig, Vorurteile zu hinterfragen.","english":"It is important to question prejudices."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss intercultural communication and cultural differences thoughtfully in German."}}',
'{"items":[{"word":"das Missverständnis","translation":"misunderstanding","pronunciation":"dahs MIS-fer-shtent-nis","example":"Ein Missverständnis klären."},{"word":"das Vorurteil","translation":"prejudice","pronunciation":"dahs FOR-oor-tyl","example":"Vorurteile abbauen."},{"word":"hinterfragen","translation":"to question/scrutinise","pronunciation":"hin-ter-FRAH-gen","example":"Vorurteile hinterfragen."},{"word":"entstehen","translation":"to arise/originate","pronunciation":"ent-SHTAY-en","example":"Probleme entstehen."},{"word":"die Integration","translation":"integration","pronunciation":"dee in-teh-grah-TSYOHN","example":"Soziale Integration."},{"word":"tolerant","translation":"tolerant","pronunciation":"toh-leh-RANT","example":"Tolerant sein."}]}',
'{"title":"Entstehen — to arise/come into being","pattern":"etwas entsteht (aus + dative) — something arises (from)","explanation":"Entstehen = to arise, come into being, originate. Missverständnisse entstehen aus Kommunikationsfehlern = Misunderstandings arise from communication errors. Aus + dative shows the source. Past: ist entstanden. Entstehen is intransitive — nothing gets entstanden deliberately; it happens. Contrast: verursachen (to cause) = active.","examples":[{"sentence":"Das Problem ist aus einem Missverständnis entstanden.","translation":"The problem arose from a misunderstanding."},{"sentence":"Neue Ideen entstehen oft in Gesprächen.","translation":"New ideas often arise in conversations."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Vorurteil'' means?","options":["prejudice","assumption","opinion","judgment"],"correctAnswer":"prejudice"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Cultural misunderstandings often arise from different communication styles.","options":["Kulturelle Missverständnisse entstehen oft durch unterschiedliche Kommunikationsstile.","Kulturen kommunizieren unterschiedlich.","Missverständnisse sind kulturell.","Verschiedene Stile führen zu Problemen."],"correctAnswer":"Kulturelle Missverständnisse entstehen oft durch unterschiedliche Kommunikationsstile."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Problem ist aus einem Missverständnis ___.","options":["entstanden","entstand","entsteht","entstehen"],"correctAnswer":"entstanden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: New ideas often arise in conversations","wordBankItems":["Neue","Ideen","entstehen","oft","in","Gesprächen","."],"correctAnswer":"Neue Ideen entstehen oft in Gesprächen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Hinterfragen'' means?","options":["to question/scrutinise","to ask behind","to wonder","to doubt"],"correctAnswer":"to question/scrutinise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German school system","Know Schularten and Abschlüsse","Compare school systems"],"explanation":{"intro":"The German school system is complex and varies by state (Bundesland). B1 learners should understand its structure.","culturalNote":"Germany has a tripartite system: Hauptschule (basic), Realschule (intermediate), Gymnasium (academic). After Gymnasium: Abitur (university entrance exam). The system is controversial — students are typically sorted at age 10. Many states now have Gesamtschulen (comprehensive schools) as an alternative."},"examples":[{"german":"In Deutschland werden Schüler nach der Grundschule in verschiedene Schulformen eingeteilt.","english":"In Germany pupils are divided into different school types after primary school."},{"german":"Das Abitur berechtigt zum Studium an einer Universität.","english":"The Abitur entitles you to study at a university."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss and explain the German school system."}}',
'{"items":[{"word":"das Abitur","translation":"A-levels equivalent/university entrance","pronunciation":"dahs ah-bee-TOOR","example":"Das Abitur machen."},{"word":"die Grundschule","translation":"primary school","pronunciation":"dee GROOND-shoo-leh","example":"In die Grundschule."},{"word":"das Gymnasium","translation":"grammar school (academic)","pronunciation":"dahs gym-NAH-zee-oom","example":"Auf dem Gymnasium."},{"word":"berechtigen zu","translation":"to entitle to","pronunciation":"beh-REKH-tee-gen tsoo","example":"Zum Studium berechtigen."},{"word":"einteilen","translation":"to divide/sort","pronunciation":"YN-ty-len","example":"In Gruppen einteilen."},{"word":"der Abschluss","translation":"school-leaving qualification","pronunciation":"dayr AP-shloos","example":"Einen Abschluss machen."}]}',
'{"title":"Berechtigen zu — to entitle to","pattern":"etwas berechtigt jemanden zu + dative (something entitles someone to)","explanation":"Berechtigen zu + dative. Das Abitur berechtigt zum Studium = The Abitur entitles you to study (zum = zu + dem). Passive: Damit ist man zum Studium berechtigt = With that one is entitled to study. Related: die Berechtigung (authorisation, entitlement). Berechtigungsnachweis = proof of entitlement.","examples":[{"sentence":"Dieser Ausweis berechtigt Sie zum Eintritt.","translation":"This pass entitles you to entry."},{"sentence":"Der Abschluss berechtigt zur Berufsausübung.","translation":"The qualification entitles you to practise the profession."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Gymnasium'' is for?","options":["academically focused students","all students","vocational training","basic education"],"correctAnswer":"academically focused students"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The Abitur entitles you to study at a university.","options":["Das Abitur berechtigt zum Studium an einer Universität.","Mit dem Abitur kann man studieren.","Das Abitur ist wichtig.","Zum Studium braucht man Abitur."],"correctAnswer":"Das Abitur berechtigt zum Studium an einer Universität."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Dieser Ausweis berechtigt Sie ___ Eintritt.","options":["zum","zu dem","für den","für"],"correctAnswer":"zum"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In Germany pupils are divided into different school types after primary school","wordBankItems":["In","Deutschland","werden","Schüler","nach","der","Grundschule","in","verschiedene","Schulformen","eingeteilt","."],"correctAnswer":"In Deutschland werden Schüler nach der Grundschule in verschiedene Schulformen eingeteilt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Der Abschluss'' means?","options":["school-leaving qualification","conclusion","completion","diploma"],"correctAnswer":"school-leaving qualification"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss university and research","Use Studium vocabulary","Talk about academic processes"],"explanation":{"intro":"University vocabulary is important for students and anyone interacting with academic environments in Germany.","culturalNote":"German universities are mostly free for EU students (few hundred euros per semester for Semesterbeitrag). The Bologna reform harmonised degrees into Bachelor/Master. Research (Forschung) is highly valued — the Humboldt model of combining teaching and research is influential globally."},"examples":[{"german":"Ich schreibe gerade meine Bachelorarbeit über erneuerbare Energien.","english":"I am currently writing my bachelor''s thesis on renewable energies."},{"german":"An deutschen Universitäten wird viel Grundlagenforschung betrieben.","english":"A lot of basic research is conducted at German universities."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss university life and academic research in German."}}',
'{"items":[{"word":"die Bachelorarbeit","translation":"bachelor''s thesis","pronunciation":"dee BAK-eh-lor-ar-byt","example":"Bachelorarbeit schreiben."},{"word":"betreiben","translation":"to conduct/pursue","pronunciation":"beh-TRY-ben","example":"Forschung betreiben."},{"word":"die Grundlagenforschung","translation":"basic/fundamental research","pronunciation":"dee GROOND-lah-gen-for-shoong","example":"Grundlagenforschung."},{"word":"das Seminar","translation":"seminar","pronunciation":"dahs seh-mee-NAHR","example":"Ein Seminar besuchen."},{"word":"die Sprechstunde","translation":"office hours","pronunciation":"dee SHPREKH-shtoond-eh","example":"Zur Sprechstunde."},{"word":"immatrikulieren","translation":"to enrol (at university)","pronunciation":"im-mat-ree-koo-LEER-en","example":"Sich immatrikulieren."}]}',
'{"title":"Betreiben — to conduct/pursue (activities)","pattern":"Forschung/Sport/Handel betreiben (to conduct research/pursue sport/do trade)","explanation":"Betreiben = to operate/conduct/pursue (irregular: betreiben → betrieb → betrieben). Forschung betreiben (conduct research), ein Geschäft betreiben (run a business), Handel betreiben (engage in trade). Strong verb: betrieben. Note: not for personal hobbies (say: ein Hobby haben/nachgehen). Used for sustained, institutional, or deliberate activities.","examples":[{"sentence":"Die Universität betreibt ein eigenes Labor.","translation":"The university operates its own laboratory."},{"sentence":"Er betreibt intensiv Sport.","translation":"He engages intensively in sport."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Immatrikulieren'' means?","options":["to enrol at university","to register","to matriculate","to sign up"],"correctAnswer":"to enrol at university"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I am currently writing my bachelor''s thesis on renewable energies.","options":["Ich schreibe gerade meine Bachelorarbeit über erneuerbare Energien.","Ich schreibe über erneuerbare Energien.","Meine Bachelorarbeit ist über Energie.","Ich studiere erneuerbare Energien."],"correctAnswer":"Ich schreibe gerade meine Bachelorarbeit über erneuerbare Energien."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Universität ___ ein eigenes Labor.","options":["betreibt","betreiben","betrieb","betreib"],"correctAnswer":"betreibt"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: A lot of basic research is conducted at German universities","wordBankItems":["An","deutschen","Universitäten","wird","viel","Grundlagenforschung","betrieben","."],"correctAnswer":"An deutschen Universitäten wird viel Grundlagenforschung betrieben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Sprechstunde'' means?","options":["office hours","speaking hour","consultation","tutorial"],"correctAnswer":"office hours"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e7',1,'APPROVED','PUBLISHED',
'{"objectives":["Navigate professional work environments","Use Arbeitskultur vocabulary","Discuss work-life balance"],"explanation":{"intro":"Professional vocabulary at B1 covers workplace culture, professional development, and work-life balance discussions.","culturalNote":"German Arbeitskultur values punctuality, thoroughness, and clear hierarchies. Work-life balance (Work-Life-Balance) is increasingly valued. Feierabend (end of work — sacred in Germany) is taken seriously. Germans are known for productive but bounded work hours."},"examples":[{"german":"In meinem Unternehmen wird Wert auf eine gute Work-Life-Balance gelegt.","english":"In my company emphasis is placed on a good work-life balance."},{"german":"Ich habe mit meinem Vorgesetzten ein Feedbackgespräch geführt.","english":"I had a feedback meeting with my line manager."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can navigate professional German workplace environments and culture."}}',
'{"items":[{"word":"der Vorgesetzte","translation":"line manager/superior","pronunciation":"dayr for-geh-ZETS-teh","example":"Mein Vorgesetzter."},{"word":"Wert legen auf","translation":"to place importance on","pronunciation":"VERT LAY-gen owf","example":"Wert auf Qualität legen."},{"word":"das Feedbackgespräch","translation":"feedback meeting","pronunciation":"dahs FEE-bak-geh-shprekh","example":"Ein Feedbackgespräch."},{"word":"die Arbeitskultur","translation":"workplace culture","pronunciation":"dee AR-byts-kool-toor","example":"Die Arbeitskultur."},{"word":"eigenverantwortlich","translation":"self-responsible/autonomous","pronunciation":"EY-gen-fer-ant-vort-likh","example":"Eigenverantwortlich arbeiten."},{"word":"das Gehalt","translation":"salary","pronunciation":"dahs geh-HALT","example":"Das Gehalt verhandeln."}]}',
'{"title":"Wert legen auf — to place importance on","pattern":"Wert auf + accusative legen (to value/place importance on something)","explanation":"Wert legen auf (to value/emphasize): Ich lege Wert auf Pünktlichkeit = I value punctuality (accusative after auf). Wert is accusative. Passive: Es wird Wert auf... gelegt = Importance is placed on... Common in professional/values contexts. Note: nicht viel Wert legen auf = not to value: Er legt keinen Wert darauf = He doesn''t care about it.","examples":[{"sentence":"Das Unternehmen legt Wert auf Teamarbeit.","translation":"The company values teamwork."},{"sentence":"Sie legt großen Wert auf ihre Unabhängigkeit.","translation":"She places great importance on her independence."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Eigenverantwortlich'' means?","options":["self-responsible/autonomous","responsible","accountable","independent"],"correctAnswer":"self-responsible/autonomous"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In my company emphasis is placed on a good work-life balance.","options":["In meinem Unternehmen wird Wert auf eine gute Work-Life-Balance gelegt.","Mein Unternehmen hat gute Work-Life-Balance.","Wir legen Wert auf Balance.","Work-Life-Balance ist wichtig."],"correctAnswer":"In meinem Unternehmen wird Wert auf eine gute Work-Life-Balance gelegt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Unternehmen legt Wert auf ___.","options":["Teamarbeit","Teamarbeit haben","Teamarbeiten","der Teamarbeit"],"correctAnswer":"Teamarbeit"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: She places great importance on her independence","wordBankItems":["Sie","legt","großen","Wert","auf","ihre","Unabhängigkeit","."],"correctAnswer":"Sie legt großen Wert auf ihre Unabhängigkeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Gehalt'' means?","options":["salary","wage","payment","income"],"correctAnswer":"salary"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss economics and business","Use Wirtschaft vocabulary","Understand economic news"],"explanation":{"intro":"Economic vocabulary at B1 allows understanding news and business discussions. Germany has one of the world''s largest economies.","culturalNote":"Germany is an export-driven economy (Exportweltmeister — formerly world export champion). The Mittelstand (small and medium enterprises) is the backbone of the economy. Companies like Volkswagen, BMW, Siemens, and Bosch are global leaders. The concept of the sozialeMarktwirtschaft (social market economy) balances free markets with social protection."},"examples":[{"german":"Deutschland hat eine exportorientierte Wirtschaft.","english":"Germany has an export-oriented economy."},{"german":"Die Inflationsrate ist im letzten Quartal gestiegen.","english":"The inflation rate rose in the last quarter."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can understand and discuss economic news and business topics in German."}}',
'{"items":[{"word":"exportorientiert","translation":"export-oriented","pronunciation":"eks-PORT-or-ee-en-teert","example":"Exportorientierte Wirtschaft."},{"word":"die Inflationsrate","translation":"inflation rate","pronunciation":"dee in-flah-TSYOHNS-rah-teh","example":"Die Inflationsrate steigt."},{"word":"das Bruttoinlandsprodukt","translation":"GDP (gross domestic product)","pronunciation":"dahs BROO-toh-in-lands-proh-dookt","example":"Das BIP wächst."},{"word":"der Mittelstand","translation":"SMEs/small and medium enterprises","pronunciation":"dayr MIT-el-shtant","example":"Der Mittelstand."},{"word":"wachsen","translation":"to grow","pronunciation":"VAK-sen","example":"Die Wirtschaft wächst."},{"word":"die Konjunktur","translation":"economic climate/business cycle","pronunciation":"dee kon-YOONK-toor","example":"Die Konjunktur."}]}',
'{"title":"Steigen/sinken — to rise/fall (economic verbs)","pattern":"steigen (rise) / sinken (fall) — strong verbs for economic data","explanation":"Steigen (to rise, climb): ist gestiegen. Die Preise sind gestiegen = Prices have risen. Sinken (to fall, decrease): ist gesunken. Die Nachfrage ist gesunken = Demand has fallen. Both are intransitive (sein auxiliary). Compare: erhöhen/senken (transitive — raise/lower deliberately): Die Bank hat die Zinsen erhöht = The bank raised interest rates.","examples":[{"sentence":"Die Arbeitslosigkeit ist auf ein Rekordtief gesunken.","translation":"Unemployment has fallen to a record low."},{"sentence":"Die Nachfrage nach erneuerbaren Energien ist stark gestiegen.","translation":"Demand for renewable energies has risen strongly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Konjunktur'' means?","options":["economic climate/business cycle","economy","market","conditions"],"correctAnswer":"economic climate/business cycle"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The inflation rate rose in the last quarter.","options":["Die Inflationsrate ist im letzten Quartal gestiegen.","Die Inflationsrate ist hoch.","Im Quartal war die Inflation höher.","Inflation stieg im Quartal."],"correctAnswer":"Die Inflationsrate ist im letzten Quartal gestiegen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Arbeitslosigkeit ist auf ein Rekordtief ___.","options":["gesunken","gestiegen","gefallen","gesenkt"],"correctAnswer":"gesunken"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Demand for renewable energies has risen strongly","wordBankItems":["Die","Nachfrage","nach","erneuerbaren","Energien","ist","stark","gestiegen","."],"correctAnswer":"Die Nachfrage nach erneuerbaren Energien ist stark gestiegen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Steigen'' uses which auxiliary in Perfekt?","options":["sein","haben","both possible","depends on context"],"correctAnswer":"sein"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000e9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss technology and innovation","Use Digitalisierung vocabulary","Talk about tech impacts on society"],"explanation":{"intro":"Technology vocabulary is increasingly important. B1 covers key terms for discussing digital transformation and innovation.","culturalNote":"Germany has a complex relationship with digitalisation (Digitalisierung). Strong data protection (Datenschutz) culture sometimes slows adoption. However, Industry 4.0 (Industrie 4.0) — the fourth industrial revolution combining manufacturing with digital technology — was coined in Germany and Germany leads in industrial automation."},"examples":[{"german":"Die Digitalisierung verändert die Arbeitswelt grundlegend.","english":"Digitalisation is fundamentally changing the working world."},{"german":"Künstliche Intelligenz bietet enorme Chancen, aber auch Risiken.","english":"Artificial intelligence offers enormous opportunities, but also risks."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss technology, innovation, and digitalisation in German."}}',
'{"items":[{"word":"die Digitalisierung","translation":"digitalisation","pronunciation":"dee dee-gee-tah-lee-ZEER-oong","example":"Die Digitalisierung."},{"word":"grundlegend","translation":"fundamental/profound","pronunciation":"GROONT-lay-gend","example":"Grundlegende Veränderung."},{"word":"die künstliche Intelligenz","translation":"artificial intelligence","pronunciation":"dee KÜNS-tlikh-eh in-tel-ee-GENTS","example":"KI entwickeln."},{"word":"die Automatisierung","translation":"automation","pronunciation":"dee ow-toh-mah-tee-ZEER-oong","example":"Durch Automatisierung."},{"word":"vernetzen","translation":"to network/connect","pronunciation":"fer-NET-sen","example":"Geräte vernetzen."},{"word":"die Disruption","translation":"disruption","pronunciation":"dee dis-roop-TSYOHN","example":"Digitale Disruption."}]}',
'{"title":"Verändern — to change (transitive) vs. sich verändern (to change itself)","pattern":"etwas verändert [object] (change something) / etwas verändert sich (something changes)","explanation":"Verändern (transitive): Die Digitalisierung verändert die Arbeitswelt = Digitalisation changes the working world. Reflexive: Die Gesellschaft verändert sich = Society is changing. Change verbs: sich wandeln (to transform), sich entwickeln (to develop), sich verschieben (to shift). Grundlegend = fundamentally (modifies the change): grundlegend verändern.","examples":[{"sentence":"Die Welt hat sich in den letzten Jahrzehnten stark verändert.","translation":"The world has changed greatly in recent decades."},{"sentence":"Technologie verändert, wie wir kommunizieren.","translation":"Technology is changing how we communicate."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Grundlegend'' means?","options":["fundamental/profound","basic","deep","substantial"],"correctAnswer":"fundamental/profound"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Digitalisation is fundamentally changing the working world.","options":["Die Digitalisierung verändert die Arbeitswelt grundlegend.","Die Arbeitswelt ändert sich durch Digitalisierung.","Digitalisation verändert alles.","Die Digitalisierung ist wichtig."],"correctAnswer":"Die Digitalisierung verändert die Arbeitswelt grundlegend."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Welt hat sich in den letzten Jahrzehnten stark ___.","options":["verändert","verändert haben","geändert","geändert haben"],"correctAnswer":"verändert"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Technology is changing how we communicate","wordBankItems":["Technologie","verändert",",","wie","wir","kommunizieren","."],"correctAnswer":"Technologie verändert , wie wir kommunizieren ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Automatisierung'' means?","options":["automation","automatisation","robotisation","mechanisation"],"correctAnswer":"automation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ea',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss media and journalism","Use Berichterstattung vocabulary","Evaluate media sources critically"],"explanation":{"intro":"Media literacy vocabulary at B1 allows discussing news, media bias, and journalism critically.","culturalNote":"Germany has a strong public broadcasting system (ARD, ZDF, Deutschlandradio) funded by Rundfunkbeitrag (broadcasting fee). Press freedom (Pressefreiheit) is constitutionally protected. Lügenpresse (lying press) became a controversial term during political debates. Faktenchecks (fact-checking) have become increasingly important."},"examples":[{"german":"Ich lese mehrere Zeitungen, um mir eine ausgewogene Meinung zu bilden.","english":"I read several newspapers in order to form a balanced opinion."},{"german":"Es ist wichtig, Nachrichten kritisch zu hinterfragen.","english":"It is important to question news critically."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss media, journalism, and media literacy in German."}}',
'{"items":[{"word":"die Berichterstattung","translation":"news coverage/reporting","pronunciation":"dee beh-RIKH-ter-shtat-oong","example":"Die Berichterstattung."},{"word":"der Faktenscheck","translation":"fact-check","pronunciation":"dayr FAK-ten-shek","example":"Einen Faktencheck machen."},{"word":"die Pressefreiheit","translation":"press freedom","pronunciation":"dee PRES-eh-fry-hyt","example":"Pressefreiheit schützen."},{"word":"parteiisch","translation":"biased/partisan","pronunciation":"par-TY-ish","example":"Parteiische Berichterstattung."},{"word":"ausgewogen berichten","translation":"to report in a balanced way","pronunciation":"OWS-geh-voh-gen beh-RIKH-ten","example":"Ausgewogen berichten."},{"word":"die Zensur","translation":"censorship","pronunciation":"dee tsen-ZOOR","example":"Gegen Zensur."}]}',
'{"title":"Sich eine Meinung bilden — to form an opinion","pattern":"sich eine Meinung bilden (über + accusative) — to form an opinion about","explanation":"Sich eine Meinung bilden = to form an opinion (reflexive). Ich bilde mir eine Meinung = I am forming an opinion. Über die Situation eine Meinung bilden (about the situation). Um sich eine Meinung zu bilden, muss man... (In order to form an opinion, one must...). Related: eine Meinung vertreten (to hold/advocate a view): Ich vertrete die Meinung, dass...","examples":[{"sentence":"Um sich eine fundierte Meinung zu bilden, sollte man verschiedene Quellen nutzen.","translation":"To form a well-founded opinion, one should use various sources."},{"sentence":"Er hat sich noch keine Meinung dazu gebildet.","translation":"He has not yet formed an opinion on that."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Parteiisch'' means?","options":["biased/partisan","political","one-sided","opinionated"],"correctAnswer":"biased/partisan"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"I read several newspapers in order to form a balanced opinion.","options":["Ich lese mehrere Zeitungen, um mir eine ausgewogene Meinung zu bilden.","Ich lese Zeitungen für eine Meinung.","Mehrere Zeitungen zu lesen ist gut.","Ich habe eine ausgewogene Meinung."],"correctAnswer":"Ich lese mehrere Zeitungen, um mir eine ausgewogene Meinung zu bilden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Er hat sich noch keine Meinung dazu ___.","options":["gebildet","geformt","gemacht","erstellt"],"correctAnswer":"gebildet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: To form a well-founded opinion one should use various sources","wordBankItems":["Um","sich","eine","fundierte","Meinung","zu","bilden",",","sollte","man","verschiedene","Quellen","nutzen","."],"correctAnswer":"Um sich eine fundierte Meinung zu bilden , sollte man verschiedene Quellen nutzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Zensur'' means?","options":["censorship","censure","review","restriction"],"correctAnswer":"censorship"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000eb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German politics","Know Bundesregierung vocabulary","Understand democratic institutions"],"explanation":{"intro":"Political vocabulary at B1 enables discussing German democracy, government structures, and current affairs.","culturalNote":"Germany is a federal parliamentary democracy. The Bundestag (federal parliament) elects the Bundeskanzler (chancellor). The Bundesrat (federal council) represents the 16 Bundesländer (federal states). Coalition governments (Koalitionen) are standard — single-party majorities are rare."},"examples":[{"german":"Der Bundestag hat das neue Gesetz verabschiedet.","english":"The Bundestag passed the new law."},{"german":"Die Koalitionsparteien haben sich auf einen Kompromiss geeinigt.","english":"The coalition parties reached a compromise."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German politics and democratic institutions in German."}}',
'{"items":[{"word":"der Bundestag","translation":"federal parliament","pronunciation":"dayr BOON-des-tahk","example":"Im Bundestag."},{"word":"verabschieden","translation":"to pass (a law)/to say goodbye","pronunciation":"fer-AP-shee-den","example":"Ein Gesetz verabschieden."},{"word":"die Koalition","translation":"coalition","pronunciation":"dee koh-ah-lee-TSYOHN","example":"Eine Koalition bilden."},{"word":"sich einigen auf","translation":"to agree on","pronunciation":"zikh EY-nee-gen owf","example":"Sich auf Kompromiss einigen."},{"word":"die Wahlbeteiligung","translation":"voter turnout","pronunciation":"dee VAHL-beh-ty-lee-goong","example":"Hohe Wahlbeteiligung."},{"word":"das Grundgesetz","translation":"Basic Law (German constitution)","pronunciation":"dahs GROOND-geh-zets","example":"Das Grundgesetz schützt."}]}',
'{"title":"Sich einigen auf — to agree on","pattern":"sich einigen auf + accusative (to agree on something)","explanation":"Sich einigen auf = to agree on/reach agreement on. Die Parteien haben sich auf einen Kompromiss geeinigt = The parties agreed on a compromise. Accusative after auf. Reflexive: einig sein (to be in agreement): Wir sind uns einig = We are in agreement. Sich einigen (reach agreement, become unanimous). Compare: zustimmen (agree/approve), einverstanden sein (to be in agreement).","examples":[{"sentence":"Die Verhandlungspartner haben sich auf einen Preis geeinigt.","translation":"The negotiating parties agreed on a price."},{"sentence":"Sie konnten sich nicht auf eine Lösung einigen.","translation":"They could not agree on a solution."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Grundgesetz'' is?","options":["Germany''s Basic Law (constitution)","the fundamental law","basic principles","founding charter"],"correctAnswer":"Germany''s Basic Law (constitution)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The coalition parties reached a compromise.","options":["Die Koalitionsparteien haben sich auf einen Kompromiss geeinigt.","Die Koalition hat einen Kompromiss.","Parteien einigten sich.","Ein Kompromiss wurde gefunden."],"correctAnswer":"Die Koalitionsparteien haben sich auf einen Kompromiss geeinigt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie konnten sich nicht auf eine Lösung ___.","options":["einigen","einig","geeinigt","einigen werden"],"correctAnswer":"einigen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The negotiating parties agreed on a price","wordBankItems":["Die","Verhandlungspartner","haben","sich","auf","einen","Preis","geeinigt","."],"correctAnswer":"Die Verhandlungspartner haben sich auf einen Preis geeinigt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Wahlbeteiligung'' means?","options":["voter turnout","election participation","voting rate","ballot count"],"correctAnswer":"voter turnout"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ec',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss climate change and environment","Use Klimawandel vocabulary","Talk about environmental policy"],"explanation":{"intro":"Climate vocabulary is essential for discussing one of the most important issues of our time. Germany has been a leader in environmental policy.","culturalNote":"Germany launched the Energiewende (energy transition) — a major policy shift toward renewable energy. Fridays for Future had massive mobilisation in Germany. Kohlenstoffdioxid (CO₂), Treibhausgas (greenhouse gas), and Nachhaltigkeit (sustainability) are mainstream vocabulary."},"examples":[{"german":"Der Klimawandel ist eine der größten Herausforderungen unserer Zeit.","english":"Climate change is one of the greatest challenges of our time."},{"german":"Deutschland hat sich verpflichtet, bis 2045 klimaneutral zu werden.","english":"Germany has committed to becoming climate-neutral by 2045."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss climate change, environment, and sustainability policy in German."}}',
'{"items":[{"word":"der Klimawandel","translation":"climate change","pronunciation":"dayr KLEE-mah-van-del","example":"Der Klimawandel."},{"word":"das Treibhausgas","translation":"greenhouse gas","pronunciation":"dahs TRY-bows-gahs","example":"Treibhausgase reduzieren."},{"word":"sich verpflichten zu","translation":"to commit to","pronunciation":"zikh fer-PFLIKH-ten tsoo","example":"Sich verpflichten."},{"word":"klimaneutral","translation":"climate-neutral","pronunciation":"KLEE-mah-noy-trahl","example":"Klimaneutral werden."},{"word":"erneuerbare Energien","translation":"renewable energies","pronunciation":"er-NOY-er-bah-reh en-ER-gee-en","example":"Erneuerbare Energien."},{"word":"die Erderwärmung","translation":"global warming","pronunciation":"dee AYRD-er-vär-moong","example":"Die Erderwärmung."}]}',
'{"title":"Sich verpflichten zu — to commit to","pattern":"sich verpflichten zu + dative noun / sich verpflichten + infinitive clause","explanation":"Sich verpflichten (to commit/pledge, reflexive). Sich verpflichten zu + dative: Deutschland hat sich zu Klimaneutralität verpflichtet = Germany has committed to climate neutrality. With infinitive: Deutschland hat sich verpflichtet, bis 2045 klimaneutral zu werden. Passive: jemanden verpflichten (to obligate someone): Er ist verpflichtet, die Kosten zu übernehmen.","examples":[{"sentence":"Die Regierung hat sich zu ehrgeizigen Klimazielen verpflichtet.","translation":"The government has committed to ambitious climate targets."},{"sentence":"Ich habe mich dazu verpflichtet, täglich Sport zu treiben.","translation":"I have committed to doing sport daily."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Erderwärmung'' means?","options":["global warming","earth heating","temperature rise","climate warming"],"correctAnswer":"global warming"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Germany has committed to becoming climate-neutral by 2045.","options":["Deutschland hat sich verpflichtet, bis 2045 klimaneutral zu werden.","Deutschland wird 2045 klimaneutral.","Deutschland hat ein Klimaziel.","Bis 2045 ist Deutschland klimaneutral."],"correctAnswer":"Deutschland hat sich verpflichtet, bis 2045 klimaneutral zu werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Regierung hat sich zu ehrgeizigen Klimazielen ___.","options":["verpflichtet","verpflichtet haben","verpflichten","verpflichtet sein"],"correctAnswer":"verpflichtet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Climate change is one of the greatest challenges of our time","wordBankItems":["Der","Klimawandel","ist","eine","der","größten","Herausforderungen","unserer","Zeit","."],"correctAnswer":"Der Klimawandel ist eine der größten Herausforderungen unserer Zeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Erneuerbare Energien'' means?","options":["renewable energies","sustainable energy","green energy","clean energy"],"correctAnswer":"renewable energies"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ed',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss urban development","Use Stadtplanung vocabulary","Talk about housing and infrastructure"],"explanation":{"intro":"Urban development vocabulary covers city planning, housing markets, and infrastructure at B1 level.","culturalNote":"German cities face housing shortages (Wohnungsnot) especially in Munich, Hamburg, and Berlin. Mietspiegel (rent index) and Mietpreisbremse (rent brake) are politically charged topics. Gentrifizierung (gentrification) is debated. German cities invest heavily in public transport (ÖPNV)."},"examples":[{"german":"In vielen deutschen Städten fehlt es an bezahlbarem Wohnraum.","english":"In many German cities there is a lack of affordable housing."},{"german":"Die Stadtplanung muss nachhaltig und zukunftsorientiert sein.","english":"Urban planning must be sustainable and future-oriented."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss urban development and city planning topics in German."}}',
'{"items":[{"word":"der Wohnraum","translation":"living space/housing","pronunciation":"dayr VOHN-rowm","example":"Bezahlbarer Wohnraum."},{"word":"bezahlbar","translation":"affordable","pronunciation":"beh-TSAHL-bar","example":"Bezahlbares Wohnen."},{"word":"die Gentrifizierung","translation":"gentrification","pronunciation":"dee gen-tree-fee-TSEER-oong","example":"Gentrifizierung stoppen."},{"word":"die Stadtplanung","translation":"urban/city planning","pronunciation":"dee SHTAHT-plah-noong","example":"Die Stadtplanung."},{"word":"die Infrastruktur","translation":"infrastructure","pronunciation":"dee in-fra-strook-TOOR","example":"Die Infrastruktur."},{"word":"zukunftsorientiert","translation":"future-oriented","pronunciation":"TSOO-koonfs-or-ee-en-teert","example":"Zukunftsorientiert planen."}]}',
'{"title":"Es fehlt an — there is a lack of","pattern":"Es fehlt an + dative (there is a lack of / something is lacking)","explanation":"Es fehlt an + dative = there is a lack of, something is lacking. Es fehlt an Wohnraum = There is a lack of housing. Es fehlt an Geld = Money is lacking. Plural: Es fehlt an Ärzten = There is a lack of doctors. More: Es mangelt an (there is a shortage of) — formal. The dative here is the thing lacking.","examples":[{"sentence":"Es fehlt an qualifizierten Fachkräften in der Pflege.","translation":"There is a lack of qualified nursing staff."},{"sentence":"Im Projekt fehlt es an Zeit und Ressourcen.","translation":"The project lacks time and resources."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Gentrifizierung'' means?","options":["gentrification","urban renewal","renovation","neighbourhood change"],"correctAnswer":"gentrification"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In many German cities there is a lack of affordable housing.","options":["In vielen deutschen Städten fehlt es an bezahlbarem Wohnraum.","Deutschen Städten fehlt Wohnraum.","Wohnraum ist teuer in Deutschland.","Es gibt wenig Wohnraum."],"correctAnswer":"In vielen deutschen Städten fehlt es an bezahlbarem Wohnraum."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Es fehlt an qualifizierten Fachkräften ___ der Pflege.","options":["in","bei","an","im"],"correctAnswer":"in"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project lacks time and resources","wordBankItems":["Im","Projekt","fehlt","es","an","Zeit","und","Ressourcen","."],"correctAnswer":"Im Projekt fehlt es an Zeit und Ressourcen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Bezahlbar'' means?","options":["affordable","payable","cheap","reasonable"],"correctAnswer":"affordable"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ee',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss key events in German history","Use historical vocabulary","Understand das Dritte Reich and Wiedervereinigung"],"explanation":{"intro":"Knowledge of German history is important for cultural understanding. B1 introduces key historical periods and their language.","culturalNote":"German history includes the Weimar Republic (1919-1933), the Third Reich (1933-1945), division into two states (1949-1989), and Reunification (Wiedervereinigung) on October 3, 1990 — now a national holiday (Tag der Deutschen Einheit). The Holocaust is taught extensively and Germany faces its past directly (Vergangenheitsbewältigung)."},"examples":[{"german":"Die Wiedervereinigung Deutschlands fand am 3. Oktober 1990 statt.","english":"The reunification of Germany took place on 3 October 1990."},{"german":"Die Aufarbeitung der Geschichte ist ein wichtiger Teil der deutschen Identität.","english":"Coming to terms with history is an important part of German identity."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss key events in German history and their significance."}}',
'{"items":[{"word":"die Wiedervereinigung","translation":"reunification","pronunciation":"dee VEE-der-fer-EY-nee-goong","example":"Die Wiedervereinigung."},{"word":"die Vergangenheitsbewältigung","translation":"coming to terms with the past","pronunciation":"dee fer-GANG-en-hyts-beh-väl-tee-goong","example":"Vergangenheitsbewältigung."},{"word":"stattfinden","translation":"to take place","pronunciation":"SHTАT-fin-den","example":"Die Feier findet statt."},{"word":"die Besatzungszone","translation":"occupation zone","pronunciation":"dee beh-ZAT-soongs-tsoh-neh","example":"Die Besatzungszonen."},{"word":"das Mauerfall","translation":"fall of the Wall","pronunciation":"dayr MOW-er-fal","example":"Der Mauerfall 1989."},{"word":"aufarbeiten","translation":"to process/work through (past)","pronunciation":"OWF-ar-by-ten","example":"Geschichte aufarbeiten."}]}',
'{"title":"Stattfinden — to take place","pattern":"stattfinden (separable) — Die Veranstaltung findet statt","explanation":"Stattfinden (separable) = to take place. Present: findet statt. Perfekt: hat stattgefunden. Die Wiedervereinigung fand 1990 statt = Reunification took place in 1990 (Imperfekt). Die Feier wird morgen stattfinden = The ceremony will take place tomorrow. Very common for events, ceremonies, meetings. Note: stattfinden is intransitive.","examples":[{"sentence":"Der Gipfel findet nächste Woche in Berlin statt.","translation":"The summit takes place next week in Berlin."},{"sentence":"Das Konzert hat wegen des Regens nicht stattgefunden.","translation":"The concert did not take place because of the rain."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Vergangenheitsbewältigung'' refers to?","options":["coming to terms with history","historical research","past events","historical awareness"],"correctAnswer":"coming to terms with history"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The reunification of Germany took place on 3 October 1990.","options":["Die Wiedervereinigung Deutschlands fand am 3. Oktober 1990 statt.","Deutschland wurde 1990 wiedervereinigt.","Am 3. Oktober ist die Einheit.","1990 war die Wiedervereinigung."],"correctAnswer":"Die Wiedervereinigung Deutschlands fand am 3. Oktober 1990 statt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Konzert hat wegen des Regens nicht ___.","options":["stattgefunden","stattfinden","stattgefand","stattfand"],"correctAnswer":"stattgefunden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The summit takes place next week in Berlin","wordBankItems":["Der","Gipfel","findet","nächste","Woche","in","Berlin","statt","."],"correctAnswer":"Der Gipfel findet nächste Woche in Berlin statt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"German reunification day is?","options":["3 October","9 November","1 May","17 June"],"correctAnswer":"3 October"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000ef',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss German literature","Know key authors and works","Use literary vocabulary"],"explanation":{"intro":"German literature has a rich tradition. B1 introduces key authors and literary vocabulary for discussing texts.","culturalNote":"German literature giants: Goethe (Faust, Werther), Schiller (Wilhelm Tell, Die Räuber), Kafka (Das Schloss, Die Verwandlung), Brecht (Mutter Courage), Thomas Mann (Buddenbrooks). Modern authors: Günter Grass, Christa Wolf. Buchhandlungen (bookshops) are celebrated — Buchhandlung = bookshop is a legal category in Germany with special pricing protection (Buchpreisbindung)."},"examples":[{"german":"Goethes Faust gilt als eines der bedeutendsten Werke der deutschen Literatur.","english":"Goethe''s Faust is considered one of the most significant works of German literature."},{"german":"Kafkas Romane beschäftigen sich mit Entfremdung und Bürokratie.","english":"Kafka''s novels deal with alienation and bureaucracy."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss German literature, authors, and literary works in German."}}',
'{"items":[{"word":"bedeutend","translation":"significant/important","pronunciation":"beh-DOY-tend","example":"Ein bedeutendes Werk."},{"word":"gelten als","translation":"to be considered as","pronunciation":"GEL-ten als","example":"Als Klassiker gelten."},{"word":"sich beschäftigen mit","translation":"to deal with/concern oneself with","pronunciation":"zikh beh-SHÄF-tee-gen mit","example":"Sich mit einem Thema beschäftigen."},{"word":"die Entfremdung","translation":"alienation","pronunciation":"dee ent-FREM-doong","example":"Kafka und Entfremdung."},{"word":"das Meisterwerk","translation":"masterpiece","pronunciation":"dahs MYS-ter-verk","example":"Ein Meisterwerk."},{"word":"veröffentlichen","translation":"to publish","pronunciation":"fer-ÖF-ent-likh-en","example":"Ein Buch veröffentlichen."}]}',
'{"title":"Gelten als — to be considered as","pattern":"gelten als + nominative complement (to be considered/regarded as)","explanation":"Gelten als (to count as / be considered as): Das gilt als Klassiker = That is considered a classic. Nominative after als (not accusative!): Er gilt als bester Autor = He is considered the best author. Past: hat als...gegolten. Strong verb: gelten → gilt → gegolten. Compare: gelten für (to apply to/be valid for): Das gilt für alle = That applies to everyone.","examples":[{"sentence":"Mozart gilt als Genie der Musikgeschichte.","translation":"Mozart is considered a genius of musical history."},{"sentence":"Das Werk gilt als das bedeutendste seiner Zeit.","translation":"The work is considered the most significant of its time."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"After ''gelten als'', the case used is?","options":["nominative","accusative","dative","genitive"],"correctAnswer":"nominative"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Goethe''s Faust is considered one of the most significant works.","options":["Goethes Faust gilt als eines der bedeutendsten Werke der deutschen Literatur.","Faust ist das wichtigste Werk.","Goethe schrieb bedeutende Werke.","Faust gilt als bedeutend."],"correctAnswer":"Goethes Faust gilt als eines der bedeutendsten Werke der deutschen Literatur."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Mozart gilt als ___ der Musikgeschichte.","options":["Genie","ein Genie","Genialer","das Genie"],"correctAnswer":"Genie"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The work is considered the most significant of its time","wordBankItems":["Das","Werk","gilt","als","das","bedeutendste","seiner","Zeit","."],"correctAnswer":"Das Werk gilt als das bedeutendste seiner Zeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Entfremdung'' means?","options":["alienation","detachment","estrangement","distance"],"correctAnswer":"alienation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000000f0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss music and art in German","Use Kunstrichtung vocabulary","Talk about musical genres and movements"],"explanation":{"intro":"Music and art vocabulary at B1 covers genres, movements, and discussing artistic works.","culturalNote":"Germany has a rich musical heritage — Beethoven, Bach, Brahms, Wagner, Handel are all German composers. The Berlin Philharmonic (Berliner Philharmoniker) is world-renowned. Germany also has a vibrant electronic music scene — Techno emerged in Berlin. The Bauhaus art movement was founded in Weimar."},"examples":[{"german":"Beethoven ist für seine sinfonischen Werke weltbekannt.","english":"Beethoven is world-famous for his symphonic works."},{"german":"Das Bauhaus hatte einen enormen Einfluss auf die moderne Architektur.","english":"The Bauhaus had an enormous influence on modern architecture."}],"rewards":{"xp":140,"coins":70},"metadata":{"estimatedMinutes":18,"canDo":"I can discuss music, art, and their cultural significance in German."}}',
'{"items":[{"word":"weltbekannt","translation":"world-famous","pronunciation":"VELT-beh-kant","example":"Weltbekannte Musik."},{"word":"der Einfluss","translation":"influence","pronunciation":"dayr YN-floos","example":"Großen Einfluss haben."},{"word":"die Kunstrichtung","translation":"artistic movement/style","pronunciation":"dee KOONST-rikh-toong","example":"Eine Kunstrichtung."},{"word":"das Sinfonieorchester","translation":"symphony orchestra","pronunciation":"dahs zin-foh-NEE-or-khes-ter","example":"Das Sinfonieorchester."},{"word":"beeinflussen","translation":"to influence","pronunciation":"beh-YN-floo-sen","example":"Stark beeinflussen."},{"word":"die Aufführung","translation":"performance/premiere","pronunciation":"dee OWF-fü-roong","example":"Eine Aufführung."}]}',
'{"title":"Einfluss haben auf — to have influence on","pattern":"Einfluss haben auf + accusative / Einfluss nehmen auf + accusative","explanation":"Einfluss haben auf + accusative: Beethoven hatte großen Einfluss auf die Romantik = Beethoven had great influence on Romanticism. Einfluss nehmen auf (to exert influence on): Er nimmt Einfluss auf die Entscheidung = He is influencing the decision. Beeinflussen (to influence, direct verb): Das beeinflusst mich = That influences me. Nominalisierung: unter dem Einfluss von (under the influence of).","examples":[{"sentence":"Der Jazz hatte großen Einfluss auf die moderne Musik.","translation":"Jazz had great influence on modern music."},{"sentence":"Das Bauhaus beeinflusste Architekten weltweit.","translation":"The Bauhaus influenced architects worldwide."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Aufführung'' means?","options":["performance/premiere","exhibition","concert","showing"],"correctAnswer":"performance/premiere"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Beethoven is world-famous for his symphonic works.","options":["Beethoven ist für seine sinfonischen Werke weltbekannt.","Beethoven war ein berühmter Komponist.","Beethoven schrieb Sinfonien.","Die Werke Beethovens sind bekannt."],"correctAnswer":"Beethoven ist für seine sinfonischen Werke weltbekannt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Jazz hatte großen Einfluss auf die moderne ___.","options":["Musik","Musikrichtung","Musiker","Musikwelt"],"correctAnswer":"Musik"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The Bauhaus influenced architects worldwide","wordBankItems":["Das","Bauhaus","beeinflusste","Architekten","weltweit","."],"correctAnswer":"Das Bauhaus beeinflusste Architekten weltweit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Beeinflussen'' means?","options":["to influence","to affect","to impact","to shape"],"correctAnswer":"to influence"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

